import{_ as t,c as a,o as i,a5 as n}from"./chunks/framework.BmNIwhaK.js";const y=JSON.parse(`{"title":"SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance","description":"Explains SyncAPIM's automatic discovery of unregistered shadow APIs, OpenAPI 3.0.1 Contract Drift comparison audits, 6 web and API attack detection rules, and real-time masking system for 8 sensitive PII categories.","frontmatter":{"title":"SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance","sidebarTitle":"WAF Threat Detection & PII Masking","description":"Explains SyncAPIM's automatic discovery of unregistered shadow APIs, OpenAPI 3.0.1 Contract Drift comparison audits, 6 web and API attack detection rules, and real-time masking system for 8 sensitive PII categories.","head":[["meta",{"name":"keywords","content":"SyncAPIM WAF, Shadow API, OpenAPI Contract Drift, SQL Injection, XSS, SSRF, RCE, JWT Verification, PII Masking"}],["meta",{"property":"og:title","content":"SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance"}],["meta",{"property":"og:description","content":"Real-time traffic-based OpenAPI 3.0.1 spec inference, Contract Drift auditing, and protection system against 6 attack types and 8 PII categories"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncapim/waf-and-pii-governance"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance | Empasy Docs"}],["meta",{"property":"og:description","content":"Explains SyncAPIM's automatic discovery of unregistered shadow APIs, OpenAPI 3.0.1 Contract Drift comparison audits, 6 web and API attack detection rules, and real-time masking system for 8 sensitive PII categories."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncapim/waf-and-pii-governance"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Explains SyncAPIM's automatic discovery of unregistered shadow APIs, OpenAPI 3.0.1 Contract Drift comparison audits, 6 web and API attack detection rules, and real-time masking system for 8 sensitive PII categories."}]],"sort":3},"headers":[],"relativePath":"en/syncapim/waf-and-pii-governance.md","filePath":"en/syncapim/waf-and-pii-governance.md","lastUpdated":1795293539000}`),o={name:"en/syncapim/waf-and-pii-governance.md"};function d(c,e,r,s,l,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="syncapim-waf-threat-detection-spec-drift-audit-and-pii-masking-governance" tabindex="-1">SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance <a class="header-anchor" href="#syncapim-waf-threat-detection-spec-drift-audit-and-pii-masking-governance" aria-label="Permalink to “SyncAPIM WAF Threat Detection, Spec Drift Audit, and PII Masking Governance”">​</a></h1><p>Going beyond simple signature-based firewalls, <code>SyncAPIM</code> provides a unified pipeline combining a <strong>lexical token fingerprint analyzer (<code>SqlXssLexicalTokenizer</code>)</strong>, <strong>real-time attack pattern detection and surgical virtual patching integrated with <code>SyncWatch</code> (<code>SandboxedDefenseEvaluator</code>)</strong>, <strong>kernel eBPF blocking</strong>, <strong>API inventory visibility (Shadow API Discovery)</strong>, <strong>live-traffic consistency verification against design specifications (Contract Drift Audit)</strong>, and <strong>personal and financial sensitive data leak prevention (PII Masking)</strong>.</p><hr><h2 id="_0-lexical-token-fingerprint-analyzer-sqlxsslexicaltokenizer-syncwatch-surgical-virtual-patching-kernel-ebpf-blocking" tabindex="-1">0. Lexical Token Fingerprint Analyzer (<code>SqlXssLexicalTokenizer</code>) + <code>SyncWatch</code> Surgical Virtual Patching + Kernel eBPF Blocking <a class="header-anchor" href="#_0-lexical-token-fingerprint-analyzer-sqlxsslexicaltokenizer-syncwatch-surgical-virtual-patching-kernel-ebpf-blocking" aria-label="Permalink to “0. Lexical Token Fingerprint Analyzer (SqlXssLexicalTokenizer) + SyncWatch Surgical Virtual Patching + Kernel eBPF Blocking”">​</a></h2><ol><li><strong>Lexical Token Fingerprint Analyzer (<code>SqlXssLexicalTokenizer</code>)</strong>: <ul><li>Completely eliminates inaccurate hash-based pseudo-vector approaches and deterministically extracts lexical token sequence fingerprints (<code>s&amp;1</code>, <code>sUE</code>, <code>;k</code>, <code>f(n)</code>, <code>x_script</code>, <code>x_event_handler</code>, etc.) within <code>0.05ms</code> after 3-stage multi-decoding (URL, HTML entity, Unicode escape, and SQL inline comment stripping) to detect variant SQLi and XSS evasion attacks.</li></ul></li><li><strong>Real-Time Attack Pattern Detection and Surgical Virtual Patching Integrated with <code>SyncWatch</code> (<code>ApimDefensePack</code> &amp; <code>SandboxedDefenseEvaluator</code>)</strong>: <ul><li>Receives in real time the <strong><code>ApimDefensePack</code></strong> compiled and verified by the enterprise security observatory <a href="/en/syncwatch/"><code>SyncWatch</code></a> from global threat feeds (NVD CVE, CISA KEV, OSV.dev, GitHub GHSA, Nuclei, OWASP CRS, KISA).</li><li><code>SandboxedDefenseEvaluator</code> (an isolated evaluator built on <code>SimpleEvaluationContext</code>) evaluates lexical token fingerprints, target-location regexes (<code>HEADER</code>, <code>URI</code>, <code>QUERY</code>, <code>BODY</code>), and Restricted SpEL expressions together to apply surgical virtual patches to specific endpoints immediately without restarting servers.</li></ul></li><li><strong>Kernel eBPF Ultra-Low-Latency Blocking</strong>: <ul><li>Source IPs and anomalous packets confirmed as high-risk intrusion attempts are dropped immediately at the kernel eBPF (XDP/TC) layer in parallel with L7 gateway blocking, proactively preventing backend resource exhaustion.</li></ul></li></ol><hr><h2 id="_1-automatic-discovery-of-unregistered-shadow-apis-and-openapi-3-0-1-inference" tabindex="-1">1. Automatic Discovery of Unregistered Shadow APIs and OpenAPI 3.0.1 Inference <a class="header-anchor" href="#_1-automatic-discovery-of-unregistered-shadow-apis-and-openapi-3-0-1-inference" aria-label="Permalink to “1. Automatic Discovery of Unregistered Shadow APIs and OpenAPI 3.0.1 Inference”">​</a></h2><ol><li><strong>Automatic Live-Traffic-Based Endpoint Catalog Generation</strong>: <ul><li><code>DetectionRuleServiceImpl</code> in <code>sync-apim-detector</code> analyzes the <code>host</code>, <code>method</code>, and <code>path</code> combinations of ingested HTTP packets and automatically registers unregistered endpoints into <code>wapf_api_endpoint</code> and <code>wapf_api_endpoint_detail</code>.</li><li>It recursively parses every field in request query strings, request bodies (JSON), and response bodies (JSON) to record data types and JSONPath expressions (such as <code>$.data.accountNo</code>) in <code>wapf_data_field</code>.</li></ul></li><li><strong>Real-Time OpenAPI 3.0.1 Spec Synthesis and Contract Drift Comparison Audit</strong>: <ul><li>Automatically synthesizes a standard OpenAPI 3.0.1 JSON specification (<code>wapf_open_api_spec</code>) based on observed input and output fields.</li><li>When <code>POST /api/v1/apim/spec/audit</code> (<code>WapfOpenApiSpecServiceImpl.auditContractDrift</code>) is invoked, it compares the design specification (<code>designSpec</code>) against the live-traffic specification to identify the following three drift types: <ul><li><strong><code>UNDOCUMENTED_RESPONSE_FIELD</code></strong>: Internal or sensitive fields not defined in the design specification are exposed in actual API responses</li><li><strong><code>MISSING_REQUIRED_PARAM</code></strong>: Requests are invoked with parameters marked as required in the design specification omitted</li><li><strong><code>SHADOW_ENDPOINT</code></strong>: Unregistered debug or legacy endpoints that do not exist in the approved API specification are invoked</li></ul></li></ul></li></ol><hr><h2 id="_2-6-standard-web-and-api-threat-detection-rules-wapf-rule" tabindex="-1">2. 6 Standard Web and API Threat Detection Rules (<code>wapf_rule</code>) <a class="header-anchor" href="#_2-6-standard-web-and-api-threat-detection-rules-wapf-rule" aria-label="Permalink to “2. 6 Standard Web and API Threat Detection Rules (wapf_rule)”">​</a></h2><p>Preloaded in <code>db/04_seed_domain.sql</code>, the 6 core threat detection rules perform real-time regular expression matching and JWT structure validation across the entire request URL, headers, query, and body.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule ID</th><th style="text-align:left;">Threat Detection Rule Name</th><th style="text-align:center;">Severity</th><th style="text-align:left;">Key Detection Patterns and Protection Targets</th></tr></thead><tbody><tr><td style="text-align:left;"><code>rule_apim_001</code></td><td style="text-align:left;"><strong>SQL Injection Attack Detection</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">Database manipulation syntax such as <code>UNION SELECT</code>, <code>OR 1=1</code>, <code>DROP TABLE</code>, <code>SLEEP()</code>, <code>WAITFOR DELAY</code></td></tr><tr><td style="text-align:left;"><code>rule_apim_002</code></td><td style="text-align:left;"><strong>Cross-Site Scripting Detection</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">Malicious script injection such as <code>&lt;script&gt;</code>, <code>javascript:</code>, <code>onerror=</code>, <code>onload=</code></td></tr><tr><td style="text-align:left;"><code>rule_apim_003</code></td><td style="text-align:left;"><strong>Server-Side Request Forgery Detection</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">Internal network probing such as <code>169.254.169.254</code> (cloud metadata), <code>localhost</code>, <code>127.0.0.1</code>, <code>file://</code>, <code>gopher://</code></td></tr><tr><td style="text-align:left;"><code>rule_apim_004</code></td><td style="text-align:left;"><strong>Remote Command Execution Attack Detection</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">OS command injection such as <code>; cat /etc/passwd</code>, <code>| bash</code>, <code>`whoami`</code>, <code>cmd.exe</code>, <code>powershell</code></td></tr><tr><td style="text-align:left;"><code>rule_apim_005</code></td><td style="text-align:left;"><strong>Directory Traversal Detection</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">Parent path bypass access such as <code>../</code>, <code>..\\\\</code>, <code>/etc/passwd</code>, <code>win.ini</code>, and URL-encoded variants</td></tr><tr><td style="text-align:left;"><code>rule_apim_006</code></td><td style="text-align:left;"><strong>JWT Token Integrity and Signature Verification</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>alg: &quot;none&quot;</code> signature bypass attacks, expired tokens (<code>exp</code> exceeded), and malformed payload structure tampering</td></tr></tbody></table><hr><h2 id="_3-7-security-policy-groups-wapf-policy-and-real-time-redis-cache-synchronization" tabindex="-1">3. 7 Security Policy Groups (<code>wapf_policy</code>) and Real-Time Redis Cache Synchronization <a class="header-anchor" href="#_3-7-security-policy-groups-wapf-policy-and-real-time-redis-cache-synchronization" aria-label="Permalink to “3. 7 Security Policy Groups (wapf_policy) and Real-Time Redis Cache Synchronization”">​</a></h2><p>When security policies or rule mappings are modified in the admin console (<code>/waf/policy</code>), <code>WapfPolicyServiceImpl.syncPolicyRuleCache()</code> executes immediately to refresh Redis (<code>wapf:policy:rules</code>), taking effect in the real-time detection pipeline without restarting <code>sync-apim-detector</code>.</p><ul><li><strong><code>pol_apim_001</code> (Authentication Security Policy)</strong>: Default (<code>basic=true</code>) global protection policy</li><li><strong><code>pol_apim_002</code> (Access Control Policy)</strong>: Access control for administrator and internal settlement APIs</li><li><strong><code>pol_apim_003</code> (Data Encryption Policy)</strong>: Protection for data in transit across financial and payment segments</li><li><strong><code>pol_apim_004</code> (Authorization Policy)</strong>: BOLA/IDOR object-level authorization verification</li><li><strong><code>pol_apim_005</code> (Network Security Policy)</strong>: SSRF defense for external callbacks and webhooks</li><li><strong><code>pol_apim_006</code> (Privacy Protection Policy)</strong>: Intensive monitoring of customer MyData query APIs</li><li><strong><code>pol_apim_007</code> (Intrusion Detection Policy)</strong>: Immediate blocking of high-risk RCE and SQLi payloads</li></ul><hr><h2 id="_4-real-time-masking-for-8-personal-and-financial-pii-categories-wapf-sensitivity" tabindex="-1">4. Real-Time Masking for 8 Personal and Financial PII Categories (<code>wapf_sensitivity</code>) <a class="header-anchor" href="#_4-real-time-masking-for-8-personal-and-financial-pii-categories-wapf-sensitivity" aria-label="Permalink to “4. Real-Time Masking for 8 Personal and Financial PII Categories (wapf_sensitivity)”">​</a></h2><p>To prevent personal data in API requests and responses from being exposed in plaintext in logs or external responses, 8 PII regular expressions are scanned in real time, masked (<code>***</code>), and automatically tagged on the corresponding field in <code>wapf_data_field.sensitivity_uuid</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Identifier</th><th style="text-align:left;">Sensitive Data Item</th><th style="text-align:center;">Severity</th><th style="text-align:left;">Target Format Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><code>sens_apim_001</code></td><td style="text-align:left;"><strong>Bank Account Number</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">Commercial bank account number format (<code>\\d{3,4}-\\d{2,6}-\\d{4,6}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_002</code></td><td style="text-align:left;"><strong>Email</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">Standard email address format</td></tr><tr><td style="text-align:left;"><code>sens_apim_003</code></td><td style="text-align:left;"><strong>Card Number</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">16-digit credit/debit card number (<code>\\d{4}-\\d{4}-\\d{4}-\\d{4}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_004</code></td><td style="text-align:left;"><strong>Resident Registration Number</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">13-digit Korean Resident Registration Number and Alien Registration Number (<code>\\d{6}-[1-4]\\d{6}</code>)</td></tr><tr><td style="text-align:left;"><code>sens_apim_005</code></td><td style="text-align:left;"><strong>Name</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">Personal name identification pattern within JSON fields</td></tr><tr><td style="text-align:left;"><code>sens_apim_006</code></td><td style="text-align:left;"><strong>Password</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">Plaintext key-value exposure of <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code></td></tr><tr><td style="text-align:left;"><code>sens_apim_007</code></td><td style="text-align:left;"><strong>IP Address</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">Internal network and client IPv4 address format</td></tr><tr><td style="text-align:left;"><code>sens_apim_008</code></td><td style="text-align:left;"><strong>Phone Number</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">Mobile and landline phone numbers (<code>01[016789]-\\d{3,4}-\\d{4}</code>)</td></tr></tbody></table>',20)])])}const m=t(o,[["render",d]]);export{y as __pageData,m as default};
